<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Ai_provider {
 public function configured(){return strlen((string)getenv('VP_OPENAI_API_KEY'))>0;}
 public function complete($messages,$requestedModel=NULL){$key=(string)getenv('VP_OPENAI_API_KEY');if(!$key)return array('ok'=>FALSE,'code'=>'AI_PROVIDER_CONFIGURATION_REQUIRED','message'=>'VP_OPENAI_API_KEY is not configured.');$base=rtrim(getenv('VP_OPENAI_BASE_URL')?:'https://api.openai.com/v1','/');$model=$requestedModel?:getenv('VP_OPENAI_MODEL');if(!$model||$model==='windels-assistant')$model='gpt-4o-mini';$payload=json_encode(array('model'=>$model,'messages'=>$messages,'stream'=>FALSE),JSON_UNESCAPED_SLASHES);$started=microtime(TRUE);if(function_exists('curl_init')){$ch=curl_init($base.'/chat/completions');curl_setopt_array($ch,array(CURLOPT_POST=>TRUE,CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>120,CURLOPT_HTTPHEADER=>array('Authorization: Bearer '.$key,'Content-Type: application/json'),CURLOPT_POSTFIELDS=>$payload));$raw=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);}else{$ctx=stream_context_create(array('http'=>array('method'=>'POST','timeout'=>120,'ignore_errors'=>TRUE,'header'=>"Authorization: Bearer $key\r\nContent-Type: application/json\r\n",'content'=>$payload)));$raw=@file_get_contents($base.'/chat/completions',FALSE,$ctx);$status=0;if(isset($http_response_header[0])&&preg_match('/\s(\d{3})\s/',$http_response_header[0],$m))$status=(int)$m[1];$error=$raw===FALSE?'HTTP transport failed':'';}if($raw===FALSE||$raw===NULL)return array('ok'=>FALSE,'code'=>'AI_PROVIDER_NETWORK_ERROR','message'=>$error?:'AI provider did not respond.');$body=json_decode($raw,TRUE);if($status<200||$status>=300)return array('ok'=>FALSE,'code'=>'AI_PROVIDER_ERROR','message'=>$body['error']['message']??('AI provider returned HTTP '.$status));$content=$body['choices'][0]['message']['content']??NULL;if(!is_string($content))return array('ok'=>FALSE,'code'=>'AI_PROVIDER_INVALID_RESPONSE','message'=>'AI provider returned no message content.');$usage=$body['usage']??array();return array('ok'=>TRUE,'content'=>$content,'model'=>$body['model']??$model,'durationMs'=>(int)round((microtime(TRUE)-$started)*1000),'tokensIn'=>(int)($usage['prompt_tokens']??0),'tokensOut'=>(int)($usage['completion_tokens']??0));}
}
